package com.kaipai.service.ai.impl; import com.kaipai.service.ai.ProfileImportRateLimiter; import java.time.Duration; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.stereotype.Component;
@Component public class RedisProfileImportRateLimiter implements ProfileImportRateLimiter { private final StringRedisTemplate redis; public RedisProfileImportRateLimiter(StringRedisTemplate redis){this.redis=redis;} public boolean allow(Long userId,int limit){String key="ai:profile-import:daily:"+java.time.LocalDate.now()+":"+userId;try{Long count=redis.opsForValue().increment(key);if(count!=null&&count==1)redis.expire(key,Duration.ofDays(1));return count!=null&&count<=limit;}catch(Exception e){return false;}}}
